static final int MAGIC = 0x4D454D42;   // "MEMB" — 이 형식인지 확인
static final short V1 = 1, V2 = 2;    // 판

// [MAGIC 4] [판 2] [건수 4] [레코드 × 건수]
o.writeInt(MAGIC);
o.writeShort(V2);
o.writeInt(ms.size());
for (Member m : ms) {
    o.writeUTF(m.name());
    o.writeInt(m.age());
    o.writeUTF(m.email());     // V2 에서 추가된 필드
}

int magic = i.readInt();
if (magic != MAGIC)
    throw new IOException(String.format(
        "이 파일 형식이 아니다: magic=%08x (기대 %08x)", magic, MAGIC));

short ver = i.readShort();
if (ver != V1 && ver != V2)
    throw new IOException("모르는 판: " + ver + " (아는 것은 1, 2)");

int n = i.readInt();
for (int k = 0; k < n; k++) {
    String name = i.readUTF();
    int age = i.readInt();
    String email = (ver >= V2) ? i.readUTF() : null;   // 여기서 갈라진다
    out.add(new Member(name, age, email));
}
